@layer hj.components {
  /* Customise: --hj-calendar-cell (day size, default 40px) · --hj-calendar-gap */
  .hj-calendar {
    --_cell: var(--hj-calendar-cell, 40px);
    display: inline-flex;
    flex-direction: column;
    gap: var(--hj-calendar-gap, calc(10px * var(--hj-density)));
    width: max-content;
    color: var(--hj-fg);
    font-family: var(--hj-font-sans);
    user-select: none;
  }

  .hj-calendar-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: calc(8px * var(--hj-density));
    padding: 0 2px;
  }
  .hj-calendar-title {
    margin: 0;
    font: var(--hj-type-heading);
    letter-spacing: var(--hj-tracking-heading);
    font-variant-numeric: tabular-nums;
  }
  .hj-calendar-nav {
    position: relative;
    display: grid;
    place-items: center;
    width: 32px;
    height: calc(32px * var(--hj-density-size));
    padding: 0;
    border: 0;
    border-radius: 50%;
    background: color-mix(in srgb, var(--hj-fg) 6%, transparent);
    color: var(--hj-fg);
    font-size: 17px;
    line-height: 0;
    cursor: pointer;
    transition:
      background-color var(--hj-dur-fast) var(--hj-ease-out),
      transform var(--hj-dur-snappy) var(--hj-ease-snappy),
      opacity var(--hj-dur-fast) var(--hj-ease-out);
  }
  .hj-calendar-nav::before {
    content: '';
    position: absolute;
    inset: -6px;
  }
  .hj-calendar-nav:hover:not(:disabled) {
    background: color-mix(in srgb, var(--hj-fg) 10%, transparent);
  }
  .hj-calendar-nav:active:not(:disabled) {
    transform: scale(0.92);
    transition-duration: 70ms;
  }
  .hj-calendar-nav:disabled {
    opacity: 0.35;
    cursor: not-allowed;
  }
  .hj-calendar-nav svg {
    width: 1em;
    height: 1em;
  }

  .hj-calendar-grid {
    border-collapse: separate;
    border-spacing: 0 2px;
    table-layout: fixed;
  }
  .hj-calendar-weekday {
    width: var(--_cell);
    height: 28px;
    padding: 0;
    font: var(--hj-type-label);
    letter-spacing: var(--hj-tracking-label);
    color: var(--hj-fg-mute);
    text-align: center;
  }
  /* The month arrives from the side it came from; under reduced motion it only fades. */
  .hj-calendar-grid[data-direction='next'] .hj-calendar-weeks {
    animation: hj-calendar-from-next var(--hj-dur-gentle-settle) var(--hj-ease-gentle-settle);
  }
  .hj-calendar-grid[data-direction='prev'] .hj-calendar-weeks {
    animation: hj-calendar-from-prev var(--hj-dur-gentle-settle) var(--hj-ease-gentle-settle);
  }
  @keyframes hj-calendar-from-next {
    from {
      opacity: 0;
      transform: translateX(calc(16px * var(--hj-travel)));
    }
  }
  @keyframes hj-calendar-from-prev {
    from {
      opacity: 0;
      transform: translateX(calc(-16px * var(--hj-travel)));
    }
  }

  .hj-calendar-cell {
    position: relative;
    width: var(--_cell);
    height: var(--_cell);
    padding: 0;
    text-align: center;
  }
  /* The range band is drawn on the cell; the ends are capped half-cells. */
  .hj-calendar-cell[data-in-range]::before,
  .hj-calendar-cell[data-in-preview]::before {
    content: '';
    position: absolute;
    inset: 0;
    background: var(--hj-accent-soft);
  }
  .hj-calendar-cell[data-in-preview]::before {
    background: color-mix(in srgb, var(--hj-accent-soft) 60%, transparent);
  }
  .hj-calendar-cell[data-range-start]::before {
    left: 50%;
  }
  .hj-calendar-cell[data-range-end]::before {
    right: 50%;
  }
  .hj-calendar-cell:first-child[data-in-range]::before,
  .hj-calendar-cell:first-child[data-in-preview]::before {
    border-radius: var(--hj-radius-pill) 0 0 var(--hj-radius-pill);
  }
  .hj-calendar-cell:last-child[data-in-range]::before,
  .hj-calendar-cell:last-child[data-in-preview]::before {
    border-radius: 0 var(--hj-radius-pill) var(--hj-radius-pill) 0;
  }

  .hj-calendar-day {
    position: relative;
    display: grid;
    place-items: center;
    width: var(--_cell);
    height: var(--_cell);
    margin: 0 auto;
    padding: 0;
    border: 0;
    border-radius: 50%;
    background: transparent;
    color: var(--hj-fg);
    font: 500 14.5px / 1 var(--hj-font-sans);
    font-variant-numeric: tabular-nums;
    cursor: pointer;
    transition:
      background-color var(--hj-dur-fast) var(--hj-ease-out),
      color var(--hj-dur-fast) var(--hj-ease-out),
      transform var(--hj-dur-snappy) var(--hj-ease-snappy);
  }
  .hj-calendar-day:hover:not([data-disabled]):not([data-selected]) {
    background: color-mix(in srgb, var(--hj-fg) 7%, transparent);
  }
  .hj-calendar-day:active:not([data-disabled]) {
    transform: scale(var(--hj-press));
    transition-duration: 70ms;
  }
  .hj-calendar-day:focus-visible {
    outline: 2px solid var(--hj-focus);
    outline-offset: 0;
  }
  .hj-calendar-day[data-outside] {
    color: var(--hj-fg-mute);
  }
  /* Today: a small mark under the number — present, never loud. */
  .hj-calendar-day[data-today]::after {
    content: '';
    position: absolute;
    bottom: 6px;
    left: calc(50% - 2px);
    width: 4px;
    height: 4px;
    border-radius: 50%;
    background: var(--hj-accent);
  }
  .hj-calendar-day[data-today] {
    font-weight: 700;
  }
  .hj-calendar-day[data-selected] {
    background: var(--hj-accent);
    color: var(--hj-on-accent);
    font-weight: 600;
    animation: hj-calendar-pick var(--hj-dur-snappy-settle) var(--hj-ease-snappy-settle);
  }
  .hj-calendar-day[data-selected][data-today]::after {
    background: var(--hj-on-accent);
  }
  @keyframes hj-calendar-pick {
    from {
      transform: scale(0.86);
    }
  }
  /* Unavailable days fade (hanji's .4); the reason belongs in words beside the calendar. */
  .hj-calendar-day[data-disabled] {
    color: var(--hj-fg-mute);
    opacity: 0.4;
    cursor: not-allowed;
  }
}

'use client';
import { useRender } from '@base-ui/react/use-render';
import * as React from 'react';

import { useHanjiConfig } from '../../system/config.tsx';
import { cls, flag, withDefaults } from '../../system/slot.ts';
import {
  addDays,
  addMonths,
  compareDay,
  isoDay,
  localeWeekStart,
  monthGrid,
  normaliseRange,
  sameDay,
  sameMonth,
  startOfDay,
  startOfMonth,
} from './dates.ts';
import type { DateRange, Weekday } from './dates.ts';

export type { DateRange, Weekday } from './dates.ts';

/** Props shared by both selection modes. */
export interface CommonOwnProps {
  /** The month shown (controlled). Any day in the month. */
  month?: Date;
  /** The month shown first. Defaults to the selection, else today. */
  defaultMonth?: Date;
  onMonthChange?: (month: Date) => void;
  /** Earliest selectable day. */
  min?: Date;
  /** Latest selectable day. */
  max?: Date;
  /** Disable individual days (holidays, sold-out dates). */
  isDateDisabled?: (date: Date) => boolean;
  /** BCP 47 locale for names and the first day of the week. Defaults to the browser's. */
  locale?: string;
  /** 0 = Sunday … 6 = Saturday. Defaults to the locale's. */
  weekStartsOn?: Weekday;
  /** Override “today” (tests, other time zones). */
  today?: Date;
}

interface SingleSelection {
  /** single = one day (default) · range = a start and an end. */
  mode?: 'single';
  value?: Date | null;
  defaultValue?: Date | null;
  onValueChange?: (value: Date | null) => void;
}
interface RangeSelection {
  mode: 'range';
  value?: DateRange;
  defaultValue?: DateRange;
  onValueChange?: (value: DateRange) => void;
}
/** Single or range selection: the value's shape follows `mode`. */
export type CalendarSelection = SingleSelection | RangeSelection;

/** Every Root prop hanji defines, as one shape (for docs and the agent manifest). */
export interface RootOwnProps extends CommonOwnProps {
  mode?: 'single' | 'range';
  value?: Date | DateRange | null;
  defaultValue?: Date | DateRange | null;
  onValueChange?: (value: Date | DateRange | null) => void;
}

export type RootProps = CalendarSelection &
  CommonOwnProps &
  Omit<React.ComponentProps<'div'>, 'defaultValue' | 'onChange' | 'children'> & {
    children?: React.ReactNode;
    render?: useRender.RenderProp;
  };

/** What `useCalendar()` returns inside a `<Calendar.Root>`. */
export interface CalendarContextValue {
  mode: 'single' | 'range';
  selected: Date | null;
  range: DateRange;
  month: Date;
  direction: 'next' | 'prev' | undefined;
  focused: Date;
  hover: Date | null;
  today: Date;
  locale: string | undefined;
  weekStartsOn: Weekday;
  titleId: string;
  canPrev: boolean;
  canNext: boolean;
  isDisabled: (d: Date) => boolean;
  select: (d: Date) => void;
  goMonth: (m: Date) => void;
  setFocused: (d: Date) => void;
  setHover: (d: Date | null) => void;
}
const CalendarContext = React.createContext<CalendarContextValue | null>(null);

/** The calendar's state, for building your own parts inside `<Calendar.Root>`. */
export function useCalendar(): CalendarContextValue {
  const ctx = React.useContext(CalendarContext);
  if (!ctx) throw new Error('Calendar parts must be inside <Calendar.Root>.');
  return ctx;
}

const EMPTY_RANGE: DateRange = { start: null, end: null };

/**
 * A month grid for picking a day or a range. No dependencies: dates are local days, names come
 * from Intl. Childless, it renders a Header and a Grid.
 *
 * @example <Calendar.Root mode="range" min={today} onValueChange={setStay} />
 */
export function Root(props: RootProps): React.ReactElement {
  const config = useHanjiConfig();
  const p = withDefaults(config, 'Calendar.Root', props);
  const {
    mode = 'single',
    value,
    defaultValue,
    onValueChange,
    month: monthProp,
    defaultMonth,
    onMonthChange,
    min,
    max,
    isDateDisabled,
    locale,
    weekStartsOn,
    today: todayProp,
    className,
    render,
    children,
    ...rest
  } = p;

  const todayKey = todayProp ? isoDay(todayProp) : isoDay(new Date());
  // oxlint-disable-next-line react/exhaustive-deps -- keyed by the calendar day, not the instant
  const today = React.useMemo(() => startOfDay(todayProp ?? new Date()), [todayKey]);

  const [inner, setInner] = React.useState<Date | DateRange | null>(
    () => defaultValue ?? (mode === 'range' ? EMPTY_RANGE : null),
  );
  const current = value !== undefined ? value : inner;
  const selected = mode === 'single' && current instanceof Date ? current : null;
  const range = mode === 'range' && current && !(current instanceof Date) ? current : EMPTY_RANGE;

  const anchor = selected ?? range.start ?? today;
  const [innerMonth, setInnerMonth] = React.useState(() => startOfMonth(defaultMonth ?? anchor));
  const month = monthProp ? startOfMonth(monthProp) : innerMonth;
  const [direction, setDirection] = React.useState<'next' | 'prev' | undefined>(undefined);
  const [focused, setFocused] = React.useState<Date>(() =>
    sameMonth(anchor, month) ? anchor : month,
  );
  const [hover, setHover] = React.useState<Date | null>(null);
  const titleId = React.useId();
  const wsOn = weekStartsOn ?? localeWeekStart(locale);

  const isDisabled = React.useCallback(
    (d: Date): boolean =>
      (min !== undefined && compareDay(d, min) < 0) ||
      (max !== undefined && compareDay(d, max) > 0) ||
      (isDateDisabled?.(d) ?? false),
    [min, max, isDateDisabled],
  );

  const goMonth = React.useCallback(
    (m: Date): void => {
      const next = startOfMonth(m);
      if (sameMonth(next, month)) return;
      setDirection(compareDay(next, month) > 0 ? 'next' : 'prev');
      if (!monthProp) setInnerMonth(next);
      onMonthChange?.(next);
    },
    [month, monthProp, onMonthChange],
  );

  const commit = React.useCallback(
    (v: Date | DateRange | null): void => {
      if (value === undefined) setInner(v);
      (onValueChange as ((x: Date | DateRange | null) => void) | undefined)?.(v);
    },
    [value, onValueChange],
  );

  const select = React.useCallback(
    (d: Date): void => {
      if (isDisabled(d)) return;
      setFocused(d);
      if (!sameMonth(d, month)) goMonth(d);
      if (mode === 'single') {
        commit(d);
        return;
      }
      if (!range.start || range.end) commit({ start: d, end: null });
      else commit(normaliseRange(range.start, d));
      setHover(null);
    },
    [isDisabled, month, goMonth, mode, commit, range.start, range.end],
  );

  const canPrev = min === undefined || compareDay(addDays(month, -1), min) >= 0;
  const canNext = max === undefined || compareDay(addMonths(month, 1), max) <= 0;

  const ctx = React.useMemo<CalendarContextValue>(
    () => ({
      mode,
      selected,
      range,
      month,
      direction,
      focused,
      hover,
      today,
      locale,
      weekStartsOn: wsOn,
      titleId,
      canPrev,
      canNext,
      isDisabled,
      select,
      goMonth,
      setFocused,
      setHover,
    }),
    [
      mode,
      selected,
      range,
      month,
      direction,
      focused,
      hover,
      today,
      locale,
      wsOn,
      titleId,
      canPrev,
      canNext,
      isDisabled,
      select,
      goMonth,
    ],
  );

  const element = useRender({
    render,
    defaultTagName: 'div',
    props: {
      role: 'group',
      'aria-labelledby': titleId,
      ...rest,
      'data-mode': mode,
      className: cls(config, 'Calendar.Root', 'hj-calendar', className) as string | undefined,
      children: children ?? (
        <>
          <Header />
          <Grid />
        </>
      ),
    },
  });
  return <CalendarContext.Provider value={ctx}>{element}</CalendarContext.Provider>;
}

export interface HeaderProps extends Omit<React.ComponentProps<'div'>, 'children'> {}

/** The month name with previous / next buttons. */
export function Header(props: HeaderProps): React.ReactElement {
  const config = useHanjiConfig();
  const { className, ...rest } = withDefaults(config, 'Calendar.Header', props);
  const c = useCalendar();
  const styled = !config.unstyled;
  const title = new Intl.DateTimeFormat(c.locale, { month: 'long', year: 'numeric' }).format(
    c.month,
  );
  return (
    <div
      {...rest}
      className={cls(config, 'Calendar.Header', 'hj-calendar-header', className) as string}
    >
      <button
        type="button"
        className={styled ? 'hj-calendar-nav' : undefined}
        aria-label={config.strings.previous}
        disabled={!c.canPrev}
        onClick={() => c.goMonth(addMonths(c.month, -1))}
      >
        {config.icons.chevronLeft}
      </button>
      <h2 id={c.titleId} className={styled ? 'hj-calendar-title' : undefined} aria-live="polite">
        {title}
      </h2>
      <button
        type="button"
        className={styled ? 'hj-calendar-nav' : undefined}
        aria-label={config.strings.next}
        disabled={!c.canNext}
        onClick={() => c.goMonth(addMonths(c.month, 1))}
      >
        {config.icons.chevronRight}
      </button>
    </div>
  );
}

export interface GridProps extends Omit<React.ComponentProps<'table'>, 'children'> {}

/** Six weeks of days, always — the grid never changes height between months. */
export function Grid(props: GridProps): React.ReactElement {
  const config = useHanjiConfig();
  const { className, onKeyDown, ...rest } = withDefaults(config, 'Calendar.Grid', props);
  const c = useCalendar();
  const ref = React.useRef<HTMLTableElement>(null);
  const keyboard = React.useRef(false);
  const styled = !config.unstyled;

  const days = monthGrid(c.month, c.weekStartsOn);
  const weeks = Array.from({ length: 6 }, (_, w) => days.slice(w * 7, w * 7 + 7));
  const short = new Intl.DateTimeFormat(c.locale, { weekday: 'short' });
  const long = new Intl.DateTimeFormat(c.locale, { weekday: 'long' });
  const full = new Intl.DateTimeFormat(c.locale, {
    weekday: 'long',
    day: 'numeric',
    month: 'long',
    year: 'numeric',
  });
  const head = days.slice(0, 7);
  // The focus target stays inside the visible month.
  const focus = sameMonth(c.focused, c.month) ? c.focused : c.month;

  React.useEffect(() => {
    if (!keyboard.current) return;
    keyboard.current = false;
    ref.current?.querySelector<HTMLButtonElement>(`[data-date="${isoDay(focus)}"]`)?.focus();
  });

  const move = (e: React.KeyboardEvent<HTMLTableElement>): void => {
    onKeyDown?.(e);
    let next: Date | null = null;
    const dow = (focus.getDay() - c.weekStartsOn + 7) % 7;
    switch (e.key) {
      case 'ArrowLeft':
        next = addDays(focus, -1);
        break;
      case 'ArrowRight':
        next = addDays(focus, 1);
        break;
      case 'ArrowUp':
        next = addDays(focus, -7);
        break;
      case 'ArrowDown':
        next = addDays(focus, 7);
        break;
      case 'Home':
        next = addDays(focus, -dow);
        break;
      case 'End':
        next = addDays(focus, 6 - dow);
        break;
      case 'PageUp':
        next = addMonths(focus, e.shiftKey ? -12 : -1);
        break;
      case 'PageDown':
        next = addMonths(focus, e.shiftKey ? 12 : 1);
        break;
      default:
        return;
    }
    e.preventDefault();
    keyboard.current = true;
    c.setFocused(next);
    if (!sameMonth(next, c.month)) c.goMonth(next);
    if (c.mode === 'range' && c.range.start && !c.range.end) c.setHover(next);
  };

  return (
    // The APG date-picker pattern: a table exposed as an interactive grid with roving focus.
    <table
      {...rest}
      ref={ref}
      // oxlint-disable-next-line jsx-a11y/no-noninteractive-element-to-interactive-role
      role="grid"
      aria-labelledby={c.titleId}
      data-direction={c.direction}
      key={isoDay(c.month)}
      onKeyDown={move}
      className={cls(config, 'Calendar.Grid', 'hj-calendar-grid', className) as string}
    >
      <thead>
        <tr>
          {head.map((d) => (
            <th
              key={d.getDay()}
              scope="col"
              abbr={long.format(d)}
              className={styled ? 'hj-calendar-weekday' : undefined}
            >
              {short.format(d)}
            </th>
          ))}
        </tr>
      </thead>
      <tbody className={styled ? 'hj-calendar-weeks' : undefined}>
        {weeks.map((week) => (
          <tr key={isoDay(week[0] as Date)}>
            {week.map((d) => (
              <Day
                key={isoDay(d)}
                date={d}
                label={full.format(d)}
                tabbable={sameDay(d, focus)}
                styled={styled}
              />
            ))}
          </tr>
        ))}
      </tbody>
    </table>
  );
}

function Day({
  date,
  label,
  tabbable,
  styled,
}: {
  date: Date;
  label: string;
  tabbable: boolean;
  styled: boolean;
}): React.ReactElement {
  const c = useCalendar();
  const outside = !sameMonth(date, c.month);
  const disabled = c.isDisabled(date);
  const { start, end } = c.range;
  const previewEnd = c.mode === 'range' && start && !end ? c.hover : null;
  const lo =
    start && (end ?? previewEnd) ? normaliseRange(start, (end ?? previewEnd) as Date) : null;
  const isStart = c.mode === 'range' && !!lo?.start && sameDay(date, lo.start);
  const isEnd = c.mode === 'range' && !!lo?.end && sameDay(date, lo.end);
  const inRange =
    !!lo?.start && !!lo.end && compareDay(date, lo.start) >= 0 && compareDay(date, lo.end) <= 0;
  const selected =
    c.mode === 'single' ? sameDay(date, c.selected) : sameDay(date, start) || sameDay(date, end);
  return (
    <td
      aria-selected={selected || undefined}
      className={styled ? 'hj-calendar-cell' : undefined}
      data-in-range={flag(inRange && !!(start && end))}
      data-in-preview={flag(inRange && !end)}
      data-range-start={flag(isStart && !sameDay(lo?.start, lo?.end))}
      data-range-end={flag(isEnd && !sameDay(lo?.start, lo?.end))}
    >
      <button
        type="button"
        tabIndex={tabbable ? 0 : -1}
        aria-label={label}
        aria-current={sameDay(date, c.today) ? 'date' : undefined}
        aria-disabled={disabled || undefined}
        data-date={isoDay(date)}
        data-today={flag(sameDay(date, c.today))}
        data-selected={flag(selected)}
        data-outside={flag(outside)}
        data-disabled={flag(disabled)}
        className={styled ? 'hj-calendar-day' : undefined}
        onClick={() => c.select(date)}
        onPointerEnter={c.mode === 'range' && start && !end ? () => c.setHover(date) : undefined}
        onFocus={() => {
          if (!sameDay(date, c.focused)) c.setFocused(date);
        }}
      >
        {date.getDate()}
      </button>
    </td>
  );
}

/** Date arithmetic on local calendar days. Every Date here is local midnight. */

export interface DateRange {
  start: Date | null;
  end: Date | null;
}

export type Weekday = 0 | 1 | 2 | 3 | 4 | 5 | 6;

export function startOfDay(d: Date): Date {
  return new Date(d.getFullYear(), d.getMonth(), d.getDate());
}

export function startOfMonth(d: Date): Date {
  return new Date(d.getFullYear(), d.getMonth(), 1);
}

export function addDays(d: Date, n: number): Date {
  return new Date(d.getFullYear(), d.getMonth(), d.getDate() + n);
}

/** Add months, clamping the day so 31 Jan + 1 month = 28/29 Feb, not 2/3 Mar. */
export function addMonths(d: Date, n: number): Date {
  const target = new Date(d.getFullYear(), d.getMonth() + n, 1);
  const last = new Date(target.getFullYear(), target.getMonth() + 1, 0).getDate();
  return new Date(target.getFullYear(), target.getMonth(), Math.min(d.getDate(), last));
}

export function sameDay(a: Date | null | undefined, b: Date | null | undefined): boolean {
  return (
    !!a &&
    !!b &&
    a.getFullYear() === b.getFullYear() &&
    a.getMonth() === b.getMonth() &&
    a.getDate() === b.getDate()
  );
}

export function sameMonth(a: Date, b: Date): boolean {
  return a.getFullYear() === b.getFullYear() && a.getMonth() === b.getMonth();
}

/** -1, 0 or 1 by calendar day. */
export function compareDay(a: Date, b: Date): number {
  const x = startOfDay(a).getTime();
  const y = startOfDay(b).getTime();
  return x < y ? -1 : x > y ? 1 : 0;
}

/** `yyyy-mm-dd`, for keys and form values (no timezone drift). */
export function isoDay(d: Date): string {
  const m = String(d.getMonth() + 1).padStart(2, '0');
  const day = String(d.getDate()).padStart(2, '0');
  return `${d.getFullYear()}-${m}-${day}`;
}

/** The 42 days (6 weeks) shown for `month`, so the grid never changes height. */
export function monthGrid(month: Date, weekStartsOn: Weekday): Date[] {
  const first = startOfMonth(month);
  const lead = (first.getDay() - weekStartsOn + 7) % 7;
  const start = addDays(first, -lead);
  return Array.from({ length: 42 }, (_, i) => addDays(start, i));
}

/** First day of the week for a locale (Intl weekInfo where supported). */
export function localeWeekStart(locale: string | undefined): Weekday {
  try {
    const loc = new Intl.Locale(
      locale ?? new Intl.DateTimeFormat().resolvedOptions().locale,
    ) as Intl.Locale & {
      getWeekInfo?: () => { firstDay: number };
      weekInfo?: { firstDay: number };
    };
    const info = loc.getWeekInfo?.() ?? loc.weekInfo;
    if (info) return (info.firstDay % 7) as Weekday;
    return loc.region === 'US' || loc.region === 'CA' || loc.region === 'JP' || loc.region === 'KR'
      ? 0
      : 1;
  } catch {
    return 1;
  }
}

/** Order a range so start ≤ end. */
export function normaliseRange(a: Date, b: Date): DateRange {
  return compareDay(a, b) <= 0 ? { start: a, end: b } : { start: b, end: a };
}

